python3 -c "import pandas as pd; import numpy as np; from scipy.stats import skew, kurtosis; train = pd.read_csv('train.csv'); X = train.drop('target', axis=1).values; y = train['target'].values;
def get_aggs(X):
    return {
        'mean': np.mean(X, axis=1),
        'std': np.std(X, axis=1),
        'min': np.min(X, axis=1),
        'max': np.max(X, axis=1),
        'sum': np.sum(X, axis=1),
        'median': np.median(X, axis=1),
        'pos': np.sum(X > 0, axis=1),
        'gt1': np.sum(X > 1, axis=1),
        'lt-1': np.sum(X < -1, axis=1),
    }
aggs = get_aggs(X)
for name, val in aggs.items():
    print(f'{name}: {np.corrcoef(val, y)[0,1]}')"

