python3 -c "import pandas as pd; import numpy as np; train = pd.read_csv('train.csv'); val = (train.drop('target', axis=1).values**2).sum(axis=1); y = train['target'].values;
best_acc = 0;
for t in np.percentile(val, np.linspace(0, 100, 20)):
    acc = max(((val > t) == y).mean(), ((val <= t) == y).mean());
    if acc > best_acc: best_acc = acc;
print(best_acc)"

